import{R as e,e as o,f as r,U as i}from"./chunks/framework.ywem4qy5.js";const u=JSON.parse('{"title":"Procurios","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/procurios.md","filePath":"integrations/crm/procurios.md","lastUpdated":1775908585000}'),n={name:"integrations/crm/procurios.md"};function a(s,t,l,c,h,g){return o(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="procurios" tabindex="-1">Procurios <a class="header-anchor" href="#procurios" aria-label="Permalink to &quot;Procurios&quot;">​</a></h1><p>Follow the below steps to connect to the Marketo API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Procurios as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-procurios-api" tabindex="-1">Step 2. Connect to the Procurios API <a class="header-anchor" href="#step-2-connect-to-the-procurios-api" aria-label="Permalink to &quot;Step 2. Connect to the Procurios API&quot;">​</a></h3><ol><li>Go to <a href="https://www.procurios.com/en/" target="_blank">Procurios</a> and login to your account.</li><li>Go to the <strong>Settings</strong> or <strong>Developers</strong> section.</li><li>Locate the area to manage <strong>OAuth Applications</strong>.</li><li>Register a new application.</li><li>In the <strong>Redirect URI</strong> field, enter the value from the <strong>Redirect URI</strong> field in Formie.</li><li>Copy the <strong>Client ID</strong> from Procurios and paste in the <strong>Client ID</strong> field in Formie.</li><li>Copy the <strong>Client Secret</strong> from Procurios and paste in the <strong>Client Secret</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to Procurios, where you must approve Formie to access your Procurios account.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const d=e(n,[["render",a]]);export{u as __pageData,d as default};
